@pytest.mark.parametrize(
    "lock_error",
    [
        BlockingIOError(
            "db_writer_lock(write_class=live) contended on test.writer-lock.live"
        ),
        sqlite3.OperationalError("database is locked"),
    ],
)
def test_live_tick_lock_contention_defers_once_without_sleep(monkeypatch, lock_error):
    from src.execution import command_recovery

    calls = []
    summary = {}

    def _contended():
        calls.append("attempt")
        raise lock_error

    monkeypatch.setattr(
        command_recovery.time,
        "sleep",
        lambda _delay: pytest.fail("live_tick DB contention must not sleep"),
    )

    assert command_recovery._run_recovery_pass_with_lock_policy(
        "first_pass",
        _contended,
        scope="live_tick",
        summary=summary,
    ) is None
    assert command_recovery._run_recovery_pass_with_lock_policy(
        "later_pass",
        _contended,
        scope="live_tick",
        summary=summary,
    ) is None

    assert calls == ["attempt"]
    assert summary == {
        "db_lock_deferred": True,
        "db_lock_deferred_at": "first_pass",
        "db_lock_deferred_count": 1,
    }


def test_capital_recovery_retries_brief_contention_within_bounded_deadline(
    monkeypatch,
):
    from src.execution import command_recovery

    attempts = 0
    now = [10.0]
    sleeps = []

    def _eventually_available():
        nonlocal attempts
        attempts += 1
        if attempts < 3:
            raise BlockingIOError(
                "db_writer_lock(write_class=live) contended on test.writer-lock.live"
            )
        return "released"

    def _sleep(delay):
        sleeps.append(delay)
        now[0] += delay

    monkeypatch.setattr(command_recovery.time, "monotonic", lambda: now[0])
    monkeypatch.setattr(command_recovery.time, "sleep", _sleep)
    summary = {}

    result = command_recovery._run_recovery_pass_with_lock_policy(
        "cancel_recovery_fast",
        _eventually_available,
        scope="live_tick",
        summary=summary,
        deadline_monotonic=11.0,
        bounded_lock_retry_delays=(0.05, 0.10, 0.20),
    )

    assert result == "released"
    assert attempts == 3
    assert sleeps == [0.05, 0.10]
    assert summary == {}


