def _insert(conn, *, command_id="cmd-001", position_id="pos-001",
            decision_id="dec-001", idempotency_key=None,
            intent_kind="ENTRY", market_id="mkt-001", token_id="tok-001",
            condition_id: str = "condition-test",
            snapshot_id: str | None = None,
            envelope_id: str | None = None,
            no_token_id: str | None = None,
            selected_token_id: str | None = None,
            outcome_label: str | None = None,
            event_slug: str | None = None,
            side="BUY", order_type="GTC", size=10.0, price=0.5,
            created_at="2026-04-26T00:00:00Z"):
    """Insert a command row and return its command_id."""
    from src.state.venue_command_repo import insert_command
    if idempotency_key is None:
        import hashlib
        # Build a unique 32-hex key per command_id so duplicate inserts don't collide.
        idempotency_key = hashlib.md5(command_id.encode()).hexdigest()
    no_token_id = no_token_id or f"{token_id}-no"
    selected_token_id = selected_token_id or token_id
    outcome_label = outcome_label or ("NO" if selected_token_id == no_token_id else "YES")
    snapshot_id = _ensure_snapshot(
        conn,
        token_id=token_id,
        snapshot_id=snapshot_id,
        condition_id=condition_id,
        no_token_id=no_token_id,
        selected_outcome_token_id=selected_token_id,
        outcome_label=outcome_label,
        event_slug=event_slug,
    )
    decision_certificate_hash = hashlib.sha256(
        f"test-certificate:{command_id}".encode()
    ).hexdigest()
    submission_envelope = None
    attached_world_for_admission = False
    if intent_kind == "ENTRY":
        schemas = {
            str(row[1]).strip()
            for row in conn.execute("PRAGMA database_list").fetchall()
            if len(row) > 1 and str(row[1]).strip()
        }
        if "world" not in schemas:
            conn.execute("ATTACH DATABASE ':memory:' AS world")
            attached_world_for_admission = True
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS world.decision_certificates (
                certificate_hash TEXT PRIMARY KEY,
                certificate_type TEXT NOT NULL,
                mode TEXT NOT NULL,
                verifier_status TEXT NOT NULL,
                payload_json TEXT NOT NULL
            )
            """
        )
        submission_envelope = _make_envelope(
            token_id=token_id,
            condition_id=condition_id,
            no_token_id=no_token_id,
            selected_outcome_token_id=selected_token_id,
            outcome_label=outcome_label,
            side=side,
            order_type=order_type,
            post_only=order_type in {"GTC", "GTD"},
            price=price,
            size=size,
        )
        direction = "buy_no" if selected_token_id == no_token_id else "buy_yes"
        conn.execute(
            """
            INSERT OR IGNORE INTO world.decision_certificates(
                certificate_hash, certificate_type, mode,
                verifier_status, payload_json
            ) VALUES (?, 'ActionableTradeCertificate', 'LIVE', 'VERIFIED', ?)
            """,
            (
                decision_certificate_hash,
                json.dumps(
                    {
                        "condition_id": condition_id,
                        "token_id": selected_token_id,
                        "direction": direction,
                    },
                    sort_keys=True,
                ),
            ),
        )
    persisted_envelope_id = (
        envelope_id or f"env-{command_id}"
        if submission_envelope is not None
        else _ensure_envelope(
            conn,
            token_id=token_id,
            condition_id=condition_id,
            no_token_id=no_token_id,
            selected_outcome_token_id=selected_token_id,
            outcome_label=outcome_label,
            side=side,
            order_type=order_type,
            price=price,
            size=size,
            envelope_id=envelope_id,
        )
    )
    insert_command(
        conn,
        command_id=command_id,
        snapshot_id=snapshot_id,
        envelope_id=persisted_envelope_id,
        submission_envelope=submission_envelope,
        position_id=position_id,
        decision_id=decision_id,
        idempotency_key=idempotency_key,
        intent_kind=intent_kind,
        market_id=market_id,
        token_id=selected_token_id,
        side=side,
        size=size,
        price=price,
        created_at=created_at,
        q_version="test-q-version",
        decision_certificate_hash=decision_certificate_hash,
    )
    if attached_world_for_admission:
        conn.commit()
        conn.execute("DETACH DATABASE world")
    return command_id


def _open_test_entry_obligation(conn, command_id: str) -> None:
    from src.state.entry_exposure_obligation import open_entry_exposure_obligation
    from src.state.schema.entry_exposure_obligations_schema import ensure_table

    ensure_table(conn)
    open_entry_exposure_obligation(
        conn,
        command_id=command_id,
        owner_domain="trade",
        token_id=f"token-{command_id}",
        condition_id=f"condition-{command_id}",
        shares=10.0,
        cost_basis_usd=5.0,
        now="2026-07-14T08:00:00+00:00",
    )


def _append_test_entry_fill(conn, command_id: str, *, with_trade: bool) -> None:
    from src.state.venue_command_repo import append_event, append_trade_fact

    at = "2026-07-14T08:00:01+00:00"
    order_id = f"order-{command_id}"
    append_event(
        conn,
        command_id=command_id,
        event_type="SUBMIT_REQUESTED",
        occurred_at=at,
        payload=_entry_submit_payload(),
    )
    append_event(
        conn,
        command_id=command_id,
        event_type="SUBMIT_ACKED",
        occurred_at=at,
        payload={"venue_order_id": order_id},
    )
    if with_trade:
        append_trade_fact(
            conn,
            trade_id=f"trade-{command_id}",
            venue_order_id=order_id,
            command_id=command_id,
            state="MATCHED",
            filled_size="10",
            fill_price="0.5",
            source="REST",
            observed_at=at,
            raw_payload_hash="f" * 64,
            raw_payload_json={"test": "terminal entry obligation"},
        )
    append_event(
        conn,
        command_id=command_id,
        event_type="FILL_CONFIRMED",
        occurred_at=at,
        payload={
            "venue_order_id": order_id,
            "trade_id": f"trade-{command_id}",
            "filled_size": "10",
            "fill_price": "0.5",
        },
    )


