def _append_test_filled_entry_projection(
    conn,
    *,
    position_id: str,
    command_id: str,
    order_id: str,
    shares: float = 10.0,
    cost_basis_usd: float = 5.0,
    size_usd: float = 5.0,
    entry_price: float = 0.5,
    event_payload: dict | None = None,
) -> None:
    from src.state.ledger import append_many_and_project

    projection = dict(
        conn.execute(
            "SELECT * FROM position_current WHERE position_id = ?",
            (position_id,),
        ).fetchone()
    )
    projection.update(
        phase="active",
        shares=shares,
        cost_basis_usd=cost_basis_usd,
        size_usd=size_usd,
        entry_price=entry_price,
        order_id=order_id,
        order_status="filled",
        updated_at="2026-07-14T08:00:02+00:00",
    )
    payload = (
        event_payload
        if event_payload is not None
        else {
            "shares": shares,
            "size_usd": size_usd,
            "entry_price": entry_price,
        }
    )
    append_many_and_project(
        conn,
        [
            {
                "event_id": f"{position_id}:filled:{command_id}",
                "position_id": position_id,
                "event_version": 1,
                "sequence_no": 3,
                "event_type": "ENTRY_ORDER_FILLED",
                "occurred_at": "2026-07-14T08:00:02+00:00",
                "phase_before": "pending_entry",
                "phase_after": "active",
                "strategy_key": "opening_inertia",
                "decision_id": "dec-001",
                "snapshot_id": "snap-pos-001",
                "order_id": order_id,
                "command_id": command_id,
                "caused_by": None,
                "idempotency_key": f"{position_id}:filled:{command_id}",
                "venue_status": "FILLED",
                "source_module": "tests.test_command_recovery",
                "env": "live",
                "payload_json": json.dumps(payload, sort_keys=True),
            }
        ],
        projection,
    )


def _settle_test_position(
    conn,
    *,
    position_id: str,
    command_id: str,
    settlement_price: float = 1.0,
    with_event: bool = True,
) -> None:
    if with_event:
        conn.execute(
            """
            INSERT INTO position_events (
                event_id, position_id, event_version, sequence_no, event_type,
                occurred_at, phase_before, phase_after, strategy_key,
                decision_id, snapshot_id, order_id, command_id, caused_by,
                idempotency_key, venue_status, source_module, env, payload_json
            )
            SELECT
                ?, ?, 1, COALESCE(MAX(sequence_no), 0) + 1, 'SETTLED',
                '2026-07-15T00:00:00+00:00', 'active', 'settled',
                'opening_inertia', 'dec-001', 'snap-pos-001', NULL, ?, NULL,
                ?, 'SETTLED', 'tests.test_command_recovery', 'live', ?
              FROM position_events
             WHERE position_id = ?
            """,
            (
                f"{position_id}:settled",
                position_id,
                command_id,
                f"{position_id}:settled",
                json.dumps({"settlement_price": settlement_price}),
                position_id,
            ),
        )
    conn.execute(
        """
        UPDATE position_current
           SET phase = 'settled',
               settlement_price = ?,
               settled_at = '2026-07-15T00:00:00+00:00',
               updated_at = '2026-07-15T00:00:00+00:00'
         WHERE position_id = ?
        """,
        (settlement_price, position_id),
    )


