def _seed_partial_exit_dust_case(
    conn,
    *,
    position_id="pos-001",
    command_id="cmd-exit",
    order_id="ord-exit",
    filled_size="156.6",
    residual="0.4",
    trade_state="CONFIRMED",
    trade_tx_hash="0xdust",
    trade_id="trade-dust",
    seed_trade=True,
):
    _insert(
        conn,
        command_id="cmd-entry",
        position_id=position_id,
        size=157.0,
        price=0.20,
    )
    _advance_to_acked(
        conn,
        command_id="cmd-entry",
        venue_order_id="ord-entry",
    )
    _seed_pending_entry_projection(
        conn,
        position_id=position_id,
        command_id="cmd-entry",
        order_id="ord-entry",
    )
    conn.execute(
        """
        UPDATE position_current
           SET phase = 'pending_exit',
               shares = ?,
               chain_state = 'synced',
               chain_shares = ?,
               chain_avg_price = 0.20,
               chain_cost_basis_usd = 0.08,
               cost_basis_usd = 0.08,
               entry_price = 0.20,
               chain_seen_at = '2026-04-26T00:09:00+00:00',
               order_id = ?,
               order_status = 'sell_pending_confirmation',
               updated_at = '2026-04-26T00:09:00+00:00'
         WHERE position_id = ?
        """,
        (residual, residual, order_id, position_id),
    )
    _seed_full_exit_intent(conn, position_id=position_id, shares=157.0)
    _insert(
        conn,
        command_id=command_id,
        position_id=position_id,
        intent_kind="EXIT",
        side="SELL",
        size=157.0,
        price=0.11,
        token_id="tok-001",
        created_at="2026-04-26T00:04:00Z",
    )
    _advance_to_partial(
        conn,
        command_id=command_id,
        venue_order_id=order_id,
    )
    if seed_trade:
        _append_trade_fact(
            conn,
            command_id=command_id,
            order_id=order_id,
            trade_id=trade_id,
            state=trade_state,
            filled_size=filled_size,
            fill_price="0.11",
            tx_hash=trade_tx_hash,
        )


def _configure_partial_exit_dust_client(
    mock_client,
    *,
    point_status,
    order_id="ord-exit",
    trade_id="trade-dust",
    matched_size="156.6",
    original_size="157",
    point_remaining="0.4",
):
    mock_client.get_open_orders.return_value = [
        {"orderID": order_id, "status": "LIVE"},
    ]
    mock_client.get_order.return_value = (
        None
        if point_status is None
        else {
            "orderID": order_id,
            "status": point_status,
            "original_size": original_size,
            "size_matched": matched_size,
            "remaining_size": point_remaining,
        }
    )
    mock_client.get_trades.return_value = [
        {
            "id": trade_id,
            "status": "CONFIRMED",
            "transaction_hash": "0xdust",
            "market": "condition-test",
            "maker_orders": [
                {
                    "order_id": order_id,
                    "asset_id": "tok-001",
                    "side": "SELL",
                    "matched_amount": matched_size,
                    "price": "0.11",
                },
            ],
        },
    ]


def _seed_cancel_pending_partial_exit_dust_case(
    conn,
    *,
    position_id="pos-001",
    command_id="cmd-exit",
    order_id="ord-exit",
    preliminary_trade=False,
    durable_partial_proof=True,
    trade_tx_hash="0xdust",
    production_evidence=False,
    filled_size="156.6",
    residual="0.4",
    seed_trade=True,
):
    from src.state.venue_command_repo import append_event

    _seed_partial_exit_dust_case(
        conn,
        position_id=position_id,
        command_id=command_id,
        order_id=order_id,
        filled_size=filled_size,
        residual=residual,
        trade_state="MATCHED" if preliminary_trade else "CONFIRMED",
        trade_tx_hash=None if preliminary_trade else trade_tx_hash,
        seed_trade=seed_trade,
    )
    append_event(
        conn,
        command_id=command_id,
        event_type="CANCEL_REQUESTED",
        occurred_at="2026-04-26T00:08:00Z",
    )
    conn.execute(
        """
        UPDATE position_current
           SET phase = CASE WHEN ? THEN 'day0_window' ELSE phase END,
               order_status = CASE WHEN ? THEN 'filled' ELSE 'backoff_exhausted' END,
               city = CASE WHEN ? THEN 'Tel Aviv' ELSE city END,
               cluster = CASE WHEN ? THEN 'Tel Aviv' ELSE cluster END,
               target_date = CASE WHEN ? THEN '2026-08-02' ELSE target_date END,
               exit_reason = 'EXIT_ORDER_TERMINAL_NO_FILL_RELEASED [DUST...0.4 below min 5]',
               updated_at = '2026-04-26T00:08:00Z'
         WHERE position_id = ?
        """,
        (
            production_evidence,
            production_evidence,
            production_evidence,
            production_evidence,
            production_evidence,
            position_id,
        ),
    )
    payload = {
        "proof_class": "terminal_partial_order_fact"
        if durable_partial_proof
        else "unproven_partial_order_fact",
        "required_predicates": {
            "terminal_order_remainder_zero": True,
            "canonical_trade_facts_match_terminal_order_fact": True,
            "cumulative_fill_below_requested_size": True,
        },
    }
    _append_order_fact(
        conn,
        command_id=command_id,
        order_id=order_id,
        state="PARTIALLY_MATCHED",
        matched_size=filled_size,
        remaining_size="0",
        raw_payload_json=payload,
    )


def test_terminal_partial_exit_release_waits_for_post_terminal_chain_observation(
    conn,
    mock_client,
    monkeypatch,
):
    from src.execution import command_recovery

    _seed_partial_exit_dust_case(conn)
    conn.execute(
        "UPDATE position_current SET chain_seen_at = ? WHERE position_id = 'pos-001'",
        ("2026-04-26T00:04:00+00:00",),
    )
    _configure_partial_exit_dust_client(
        mock_client,
        point_status="CANCELED",
    )
    monkeypatch.setattr(
        command_recovery,
        "_now_iso",
        lambda: "2026-04-26T00:09:00+00:00",
    )

    terminalized = command_recovery.reconcile_partial_remainders(
        conn,
        mock_client,
        live_tick_scope=True,
    )
    stale_release = command_recovery.reconcile_pending_exit_terminal_order_releases(
        conn,
    )

    assert terminalized == {"scanned": 1, "advanced": 1, "stayed": 0, "errors": 0}
    assert stale_release == {"scanned": 0, "advanced": 0, "stayed": 0, "errors": 0}
    assert conn.execute(
        "SELECT phase FROM position_current WHERE position_id = 'pos-001'",
    ).fetchone()[0] == "pending_exit"

    conn.execute(
        "UPDATE position_current SET chain_seen_at = ? WHERE position_id = 'pos-001'",
        ("2026-04-26T00:10:00+00:00",),
    )
    fresh_release = command_recovery.reconcile_pending_exit_terminal_order_releases(
        conn,
    )

    assert fresh_release == {"scanned": 1, "advanced": 1, "stayed": 0, "errors": 0}
    assert conn.execute(
        "SELECT phase FROM position_current WHERE position_id = 'pos-001'",
    ).fetchone()[0] == "active"


def _connect_file_db(path):
    from src.state.db import init_schema, init_schema_trade_only
    from src.state.collateral_ledger import init_collateral_schema

    c = sqlite3.connect(path)
    c.row_factory = sqlite3.Row
    init_schema(c)
    init_schema_trade_only(c)
    return c


@pytest.mark.parametrize("partial_status", ["PARTIAL", "PARTIALLY_MATCHED", "PARTIALLY_FILLED"])
def test_partial_polling_with_trade_id_projects_optimistic_lot(tmp_path, partial_status):
    """PARTIAL with real trade id is optimistic exposure, not synthetic finality."""
    from src.execution.fill_tracker import _maybe_append_venue_fill_observation
    from src.state.portfolio import Position

    db_path = tmp_path / "partial-fill.db"
    conn = _connect_file_db(db_path)
    _insert(
        conn,
        command_id="cmd-partial",
        position_id="runtime-pos-partial",
        decision_id="dec-partial",
        token_id="tok-partial",
        side="BUY",
        size=10.0,
        price=0.5,
    )
    conn.execute(
        "UPDATE venue_commands SET venue_order_id = ? WHERE command_id = ?",
        ("vord-partial", "cmd-partial"),
    )
    conn.execute(
        """
        INSERT INTO trade_decisions (
            market_id, bin_label, direction, size_usd, price, timestamp,
            p_raw, p_posterior, edge, ci_lower, ci_upper, kelly_fraction,
            status, runtime_trade_id
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            "mkt-001",
            "50-51°F",
            "buy_yes",
            10.0,
            0.5,
            _NOW.isoformat(),
            0.6,
            0.6,
            0.1,
            0.05,
            0.15,
            0.0,
            "pending",
            "runtime-pos-partial",
        ),
    )
    conn.commit()
    conn.close()

    pos = Position(
        trade_id="runtime-pos-partial",
        market_id="mkt-001",
        city="Paris",
        cluster="Paris",
        target_date="2026-04-26",
        bin_label="50-51°F",
        direction="buy_yes",
        size_usd=10.0,
        entry_price=0.5,
        shares=20.0,
        state="pending_tracked",
        order_id="vord-partial",
        entry_order_id="vord-partial",
    )
    deps = SimpleNamespace(get_connection=lambda: _connect_file_db(db_path))

    assert _maybe_append_venue_fill_observation(
        pos,
        {
            "status": partial_status,
            "trade_id": "venue-trade-partial",
            "filled_size": "4.25",
            "price": "0.5",
        },
        status=partial_status,
        shares=4.25,
        fill_price=0.5,
        observed_at=_NOW,
        deps=deps,
    )

    verify = _connect_file_db(db_path)
    try:
        order_fact = verify.execute(
            "SELECT state, matched_size FROM venue_order_facts WHERE venue_order_id = ?",
            ("vord-partial",),
        ).fetchone()
        trade_fact = verify.execute(
            "SELECT trade_fact_id, state, filled_size FROM venue_trade_facts WHERE trade_id = ?",
            ("venue-trade-partial",),
        ).fetchone()
        lot = verify.execute(
            "SELECT state, shares FROM position_lots WHERE source_trade_fact_id = ?",
            (trade_fact["trade_fact_id"],),
        ).fetchone()
    finally:
        verify.close()

    assert dict(order_fact) == {"state": "PARTIALLY_MATCHED", "matched_size": "4.25"}
    assert {key: trade_fact[key] for key in ("state", "filled_size")} == {
        "state": "MATCHED",
        "filled_size": "4.25",
    }
    assert lot["state"] == "OPTIMISTIC_EXPOSURE"
    assert Decimal(str(lot["shares"])) == Decimal("4.25")


# ---------------------------------------------------------------------------
# TestRecoveryResolutionTable
# ---------------------------------------------------------------------------

class TestRecoveryResolutionTable:
    """Cover all 8 INV-31 anchor resolution-table cases."""

    # Case 1: SUBMITTING + venue_order_id + venue finds order u2192 ACKED
    def test_submitting_with_venue_order_resolves_to_acked(self, conn, mock_client):
        _insert(conn)
        _advance_to_submitting(conn, venue_order_id="vord-001")
        mock_client.get_order.return_value = {"orderID": "vord-001", "status": "LIVE"}

        from src.execution.command_recovery import reconcile_unresolved_commands
        summary = reconcile_unresolved_commands(conn, mock_client)

        assert _get_state(conn, "cmd-001") == "ACKED"
        assert summary["advanced"] == 1
        assert summary["scanned"] == 1
        events = _get_events(conn, "cmd-001")
        event_types = [e["event_type"] for e in events]
        assert "SUBMIT_ACKED" in event_types

    def test_submitting_with_order_state_resolves_to_acked(self, conn, mock_client):
        _insert(conn)
        _advance_to_submitting(conn, venue_order_id="vord-state")
        mock_client.get_order.return_value = SimpleNamespace(
            order_id="vord-state",
            status="LIVE",
            raw={"orderID": "vord-state", "status": "LIVE"},
        )

        from src.execution.command_recovery import reconcile_unresolved_commands

        summary = reconcile_unresolved_commands(conn, mock_client)

        assert _get_state(conn, "cmd-001") == "ACKED"
        assert summary["advanced"] == 1
        events = _get_events(conn, "cmd-001")
        ack = [e for e in events if e["event_type"] == "SUBMIT_ACKED"][-1]
        payload = json.loads(ack["payload_json"])
        assert payload["venue_response"] == {"orderID": "vord-state", "status": "LIVE"}

    def test_submitting_rejects_empty_normalized_venue_order_payload(
        self, conn, mock_client
    ):
        _insert(conn)
        _advance_to_submitting(conn, venue_order_id="vord-empty")
        mock_client.get_order.return_value = object()

        from src.execution.command_recovery import reconcile_unresolved_commands

        summary = reconcile_unresolved_commands(conn, mock_client)

        assert _get_state(conn, "cmd-001") == "REVIEW_REQUIRED"
        assert summary["advanced"] == 1
        events = _get_events(conn, "cmd-001")
        assert "SUBMIT_ACKED" not in [e["event_type"] for e in events]
        review = [e for e in events if e["event_type"] == "REVIEW_REQUIRED"][-1]
        payload = json.loads(review["payload_json"])
        assert payload == {
            "reason": "recovery_order_not_found_at_venue",
            "venue_order_id": "vord-empty",
        }

    def test_bound_entry_authenticated_absence_terminalizes_zero_exposure(
        self,
        conn,
        monkeypatch,
    ):
        """Exact point/account absence must release a bound no-fill ENTRY."""
        from src.execution import command_recovery
        from src.state.venue_command_repo import append_event
        from src.venue.response_contracts import VenueOrderNotFound

        command_id = "cmd-bound-entry-absent"
        position_id = "pos-bound-entry-absent"
        order_id = "ord-bound-entry-absent"
        token_id = "tok-bound-entry-absent"
        _insert(
            conn,
            command_id=command_id,
            position_id=position_id,
            token_id=token_id,
            size=12,
            price=0.51,
        )
        _advance_to_submitting(
            conn,
            command_id=command_id,
            venue_order_id=order_id,
        )
        _seed_pending_entry_projection(
            conn,
            position_id=position_id,
            command_id=command_id,
            order_id=order_id,
            token_id=token_id,
        )
        append_event(
            conn,
            command_id=command_id,
            event_type="REVIEW_REQUIRED",
            occurred_at="2026-04-26T00:03:00+00:00",
            payload={
                "reason": "recovery_order_not_found_at_venue",
                "venue_order_id": order_id,
            },
        )

        class CompleteVenue:
            venue_reads_are_complete = True
            authenticated_point_reads_are_complete = True

            @staticmethod
            def get_order(read_order_id):
                raise VenueOrderNotFound(read_order_id)

            @staticmethod
            def get_open_orders():
                return []

            @staticmethod
            def get_trades():
                return []

        monkeypatch.setattr(
            command_recovery,
            "_now_iso",
            lambda: "2026-04-26T00:05:00+00:00",
        )

        summary = command_recovery.reconcile_unresolved_commands(
            conn,
            CompleteVenue(),
        )

        assert summary["advanced"] == 1
        assert _get_state(conn, command_id) == "EXPIRED"
        fact = conn.execute(
            """
            SELECT state, matched_size, remaining_size, raw_payload_json
              FROM venue_order_facts
             WHERE command_id = ?
             ORDER BY local_sequence DESC
             LIMIT 1
            """,
            (command_id,),
        ).fetchone()
        assert {
            "state": fact["state"],
            "matched_size": fact["matched_size"],
            "remaining_size": fact["remaining_size"],
        } == {
            "state": "VENUE_WIPED",
            "matched_size": "0",
            "remaining_size": "0",
        }
        terminal = json.loads(fact["raw_payload_json"])
        assert terminal["venue_read_proof"]["point_order_query_complete"] is True
        assert terminal["venue_read_proof"]["point_order_absent"] is True
        event = _get_events(conn, command_id)[-1]
        payload = json.loads(event["payload_json"])
        assert event["event_type"] == "REVIEW_CLEARED_NO_VENUE_EXPOSURE"
        assert payload["proof_class"] == "bound_entry_terminal_no_fill"
        assert payload["venue_absence_proof"]["point_order_absence_reason"] == (
            "authenticated_order_404"
        )
        projection = conn.execute(
            "SELECT phase, shares, cost_basis_usd FROM position_current "
            "WHERE position_id = ?",
            (position_id,),
        ).fetchone()
        assert dict(projection) == {
            "phase": "voided",
            "shares": 0.0,
            "cost_basis_usd": 0.0,
        }

        # The final append boundary must independently reject forged remote
        # completeness even after a real terminal fact exists locally.
        forged = json.loads(event["payload_json"])
        forged["venue_absence_proof"]["point_order_query_complete"] = False
        conn.execute(
            "DELETE FROM venue_command_events WHERE event_id = ?",
            (event["event_id"],),
        )
        latest = conn.execute(
            """
            SELECT event_id, occurred_at
              FROM venue_command_events
             WHERE command_id = ?
             ORDER BY sequence_no DESC
             LIMIT 1
            """,
            (command_id,),
        ).fetchone()
        conn.execute(
            "UPDATE venue_commands SET state = 'REVIEW_REQUIRED', "
            "last_event_id = ?, updated_at = ? WHERE command_id = ?",
            (latest["event_id"], latest["occurred_at"], command_id),
        )
        with pytest.raises(ValueError, match="point_order_query_complete"):
            append_event(
                conn,
                command_id=command_id,
                event_type="REVIEW_CLEARED_NO_VENUE_EXPOSURE",
                occurred_at="2026-04-26T00:05:01+00:00",
                payload=forged,
            )

