    @pytest.mark.parametrize("deterministic_order_id", [None, "0xdeterministic-exit"])
    def test_restart_preflight_recovers_no_venue_exit_into_retry_projection(
        self,
        tmp_path,
        monkeypatch,
        deterministic_order_id,
    ):
        from src.execution import command_recovery, venue_sync_contract
        from src.state.db import init_schema, init_schema_trade_only
        from src.state.collateral_ledger import init_collateral_schema

        db_path = tmp_path / "restart-preflight.db"
        seed = sqlite3.connect(db_path)
        seed.row_factory = sqlite3.Row
        init_schema(seed)
        init_schema_trade_only(seed)
        init_collateral_schema(seed)
        _seed_pending_entry_projection(
            seed,
            position_id="pos-exit",
            command_id="cmd-entry",
            order_id="ord-entry",
        )
        seed.execute(
            """
            UPDATE position_current
               SET phase = 'pending_exit',
                   shares = 21.42,
                   chain_shares = 21.42,
                   cost_basis_usd = 14.35,
                   entry_price = 0.67,
                   order_status = 'filled',
                   exit_reason = 'FAMILY_DIRECT_SELL_DOMINATES_HOLD',
                   chain_state = 'synced',
                   updated_at = '2026-06-29T05:08:33+00:00'
             WHERE position_id = 'pos-exit'
            """
        )
        _insert(
            seed,
            command_id="cmd-exit",
            position_id="pos-exit",
            decision_id="exit:pos-exit",
            intent_kind="EXIT",
            side="SELL",
            size=21.42,
            price=0.58,
            created_at="2026-06-29T05:08:33+00:00",
        )
        _advance_to_submitting(
            seed,
            command_id="cmd-exit",
            venue_order_id=deterministic_order_id,
        )
        if deterministic_order_id is not None:
            from src.state.venue_command_repo import append_event

            append_event(
                seed,
                command_id="cmd-exit",
                event_type="SUBMIT_TIMEOUT_UNKNOWN",
                occurred_at="2026-06-29T05:08:34+00:00",
                payload={"reason": "post_submit_exception_possible_side_effect"},
            )
            append_event(
                seed,
                command_id="cmd-exit",
                event_type="SUBMIT_REJECTED",
                occurred_at="2026-06-29T05:25:34+00:00",
                payload={
                    "reason": "safe_replay_permitted_no_order_found",
                    "safe_replay_permitted": True,
                    "lookup_method": "venue_order_id",
                },
            )
            seed.execute(
                """
                UPDATE position_current
                   SET order_status = 'retry_pending',
                       exit_retry_count = 1,
                       next_exit_retry_at = '2026-06-29T05:25:34+00:00'
                 WHERE position_id = 'pos-exit'
                """
            )
        _insert(
            seed,
            command_id="cmd-review-old",
            position_id="pos-review-old",
            decision_id="dec-review-old",
            intent_kind="ENTRY",
            side="BUY",
            size=8.0,
            price=0.56,
            created_at="2026-06-23T19:13:43+00:00",
        )
        _advance_to_submitting(seed, command_id="cmd-review-old", venue_order_id=None)
        from src.state.venue_command_repo import append_event

        append_event(
            seed,
            command_id="cmd-review-old",
            event_type="REVIEW_REQUIRED",
            occurred_at="2026-06-23T19:13:47+00:00",
            payload={"reason": "recovery_no_venue_order_id"},
        )
        seed.commit()
        seed.close()

        def _conn_factory():
            conn = sqlite3.connect(db_path)
            conn.row_factory = sqlite3.Row
            return conn

        monkeypatch.setattr(
            venue_sync_contract,
            "default_trade_conn_factory",
            _conn_factory,
        )
        client = MagicMock(
            spec_set=[
                "get_order",
                "get_open_orders",
                "get_trades",
                "get_account_truth",
                "get_clob_market_info",
            ]
        )
        client.get_account_truth.return_value = SimpleNamespace(
            open_orders=[],
            trades=[],
        )
        client.get_open_orders.return_value = []
        client.get_trades.return_value = []
        client.get_order.return_value = None

        summary = command_recovery.reconcile_unresolved_commands(
            client=client,
            scope="restart_preflight",
        )

        check = sqlite3.connect(db_path)
        check.row_factory = sqlite3.Row
        current = check.execute(
            """
            SELECT phase, order_status, exit_retry_count, next_exit_retry_at
              FROM position_current
             WHERE position_id = 'pos-exit'
            """
        ).fetchone()
        command_state = _get_state(check, "cmd-exit")
        latest_event = check.execute(
            """
            SELECT event_type, venue_status, payload_json
              FROM position_events
             WHERE position_id = 'pos-exit'
             ORDER BY sequence_no DESC
             LIMIT 1
            """
        ).fetchone()
        check.close()

        assert summary["scope"] == "restart_preflight"
        assert summary["restart_preflight_narrow"] is True
        assert summary["scanned"] == (0 if deterministic_order_id else 1)
