    @pytest.mark.parametrize(
        ("event_type", "reason"),
        (
            (
                "CANCEL_FAILED",
                "order can't be found - already canceled or matched",
            ),
            (
                "CANCEL_REPLACE_BLOCKED",
                "post_cancel_unknown_possible_side_effect",
            ),
        ),
    )
    def test_live_tick_prioritizes_cancel_review_before_general_budget(
        self,
        tmp_path,
        monkeypatch,
        mock_client,
        event_type,
        reason,
    ):
        """Capital-blocking cancel proof runs even when broad DB budget is zero."""
        from src.execution import command_recovery, venue_sync_contract
        from src.state.collateral_ledger import init_collateral_schema
        from src.state.db import init_schema, init_schema_trade_only
        from src.state.venue_command_repo import append_event

        db_path = tmp_path / "priority-cancel-review.db"
        seed = sqlite3.connect(db_path)
        seed.row_factory = sqlite3.Row
        init_schema(seed)
        init_schema_trade_only(seed)
        init_collateral_schema(seed)
        _insert(seed, size=60.0, price=0.71)
        _advance_to_acked(seed, venue_order_id="ord-priority-unfilled")
        _seed_pending_entry_projection(seed, order_id="ord-priority-unfilled")
        append_event(
            seed,
            command_id="cmd-001",
            event_type="CANCEL_REQUESTED",
            occurred_at="2026-04-26T00:07:00Z",
            payload={"venue_order_id": "ord-priority-unfilled"},
        )
        append_event(
            seed,
            command_id="cmd-001",
            event_type=event_type,
            occurred_at="2026-04-26T00:08:00Z",
            payload={
                "venue_order_id": "ord-priority-unfilled",
                "reason": reason,
                "semantic_cancel_status": (
                    "CANCEL_UNKNOWN"
                    if event_type == "CANCEL_REPLACE_BLOCKED"
                    else None
                ),
                "requires_m5_reconcile": event_type == "CANCEL_REPLACE_BLOCKED",
                "cancel_outcome": {
                    "orderID": "ord-priority-unfilled",
                    "status": "NOT_CANCELED",
                    "errorMessage": "order can't be found - already canceled or matched",
                },
            },
        )
        seed.commit()
        seed.close()

        def _conn_factory(**_kwargs):
            conn = sqlite3.connect(db_path)
            conn.row_factory = sqlite3.Row
            return conn

        capital_apply_calls = []

        def _trade_only_conn_factory(**_kwargs):
            capital_apply_calls.append("trade_only")
            return _conn_factory()

        _conn_factory.trade_only_factory = _trade_only_conn_factory
        _conn_factory.requires_writer_flocks = True
        _trade_only_conn_factory.requires_writer_flocks = True

        priority_deadlines = []

        def _priority_factory_spy(
            conn_factory,
            *,
            scope,
            deadline_monotonic=None,
        ):
            priority_deadlines.append((conn_factory, scope, deadline_monotonic))
            return conn_factory

        monkeypatch.setattr(
            command_recovery,
            "_recovery_priority_conn_factory",
            _priority_factory_spy,
        )

        monkeypatch.setattr(
            venue_sync_contract,
            "default_trade_conn_factory",
            _conn_factory,
        )
        monkeypatch.setattr(
            venue_sync_contract,
            "default_trade_read_conn_factory",
            _conn_factory,
        )
        monkeypatch.setenv("ZEUS_LIVE_RECOVERY_DB_BUDGET_SECONDS", "0")
        mock_client.get_order.return_value = {
            "orderID": "ord-priority-unfilled",
            "status": "CANCELED",
            "original_size": "60",
            "size_matched": "0",
        }
        mock_client.get_open_orders.return_value = []
        mock_client.get_trades.return_value = []

        summary = command_recovery.reconcile_unresolved_commands(
            client=mock_client,
            scope="live_tick",
        )

        assert summary["cancel_recovery_fast"] == {
            "scanned": 1,
            "advanced": 1,
            "stayed": 0,
            "errors": 0,
        }
        assert capital_apply_calls
        assert len(priority_deadlines) == 2
        general_deadline = priority_deadlines[0][2]
        capital_deadline = priority_deadlines[1][2]
        assert priority_deadlines[1][0] is _trade_only_conn_factory
        assert capital_deadline > general_deadline + 1.0
        verified = _conn_factory()
        try:
            assert _get_state(verified, "cmd-001") == "EXPIRED"
        finally:
            verified.close()

