    def test_edli_filled_entry_recovery_binds_exact_global_auction_receipt(
        self,
        conn,
        mock_client,
    ):
        """A recovered fill remains settlement-grade attributable to its winner cut."""

        from src.execution.command_recovery import (
            _verified_edli_global_auction_decision_log_id,
            reconcile_unresolved_commands,
        )
        from src.state.venue_command_repo import append_event

        event_id = "edli_evt_global_receipt_projection"
        decision_id = (
            f"edli_exec_cmd:{event_id}:intent:tok-001-no:tok-001-no:buy_no"
        )
        _insert(
            conn,
            decision_id=decision_id,
            token_id="tok-001",
            no_token_id="tok-001-no",
            selected_token_id="tok-001-no",
            outcome_label="NO",
            size=5.0,
            price=0.34,
        )
        _advance_to_acked(conn, venue_order_id="ord-global-receipt")
        append_event(
            conn,
            command_id="cmd-001",
            event_type="FILL_CONFIRMED",
            occurred_at="2026-04-26T00:06:00Z",
            payload={
                "venue_order_id": "ord-global-receipt",
                "venue_status": "MATCHED",
            },
        )
        _append_trade_fact(
            conn,
            order_id="ord-global-receipt",
            state="MATCHED",
            filled_size="5",
            fill_price="0.34",
        )
        receipt_row_id, global_binding = (
            _insert_global_auction_receipt_for_recovery(
                conn,
                event_id=event_id,
            )
        )
        certificate_hash = _insert_actionable_certificate_for_recovery(
            conn,
            event_id=event_id,
            token_id="tok-001-no",
            q_live=0.91,
            direction="buy_no",
            global_auction_binding=global_binding,
        )
        conn.execute("ATTACH DATABASE ':memory:' AS world")
        conn.execute(
            "CREATE TABLE world.decision_certificates AS "
            "SELECT * FROM main.decision_certificates WHERE 0"
        )
        conn.execute(
            "INSERT INTO world.decision_certificates "
            "SELECT * FROM main.decision_certificates WHERE certificate_hash = ?",
            (certificate_hash,),
        )

        mismatched = dict(global_binding)
        mismatched["global_candidate_id"] = "different-candidate"
        assert _verified_edli_global_auction_decision_log_id(
            conn,
            event_id=event_id,
            economics=mismatched,
        ) is None

        summary = reconcile_unresolved_commands(conn, mock_client)
        assert summary["filled_entry_projection_repair"]["advanced"] == 1
        filled_payload = json.loads(
            conn.execute(
                """
                SELECT payload_json
                  FROM position_events
                 WHERE position_id = 'pos-001'
                   AND event_type = 'ENTRY_ORDER_FILLED'
                """
            ).fetchone()[0]
        )
        assert filled_payload["decision_log_id"] == receipt_row_id

    def test_edli_trade_case_marks_non_qkernel_actionable_as_venue_fact_recovery(
        self,
        conn,
    ):
        from src.execution.command_recovery import _edli_trade_case_for_command

        event_id = "edli_evt_legacy_actionable"
        token_id = "tok-no"
        decision_id = f"edli_exec_cmd:{event_id}:intent:{token_id}:{token_id}:buy_no"

        def insert_certificate(certificate_type: str, semantic_key: str, payload: dict, created_at: str) -> None:
            payload_json = json.dumps(payload, sort_keys=True)
            payload_hash = hashlib.sha256(payload_json.encode()).hexdigest()
            conn.execute(
                """
                INSERT INTO decision_certificates (
                    certificate_id, certificate_type, schema_version, canonicalization_version,
                    semantic_key, claim_type, mode, decision_time, authority_id,
                    authority_version, algorithm_id, algorithm_version, payload_json,
                    payload_hash, certificate_hash, verifier_status, created_at
                ) VALUES (?, ?, 1, 'test', ?, 'test', 'LIVE', ?, 'test',
                          'test', 'test', 'test', ?, ?, ?, 'VERIFIED', ?)
                """,
                (
                    f"cert:{certificate_type}:{semantic_key}",
                    certificate_type,
                    semantic_key,
                    created_at,
                    payload_json,
                    payload_hash,
                    hashlib.sha256(f"{certificate_type}:{payload_hash}".encode()).hexdigest(),
                    created_at,
                ),
            )

        insert_certificate(
            "ActionableTradeCertificate",
            f"actionable:{event_id}:family:condition-1",
            {
                "event_id": event_id,
                "event_type": "FORECAST_SNAPSHOT_READY",
                "condition_id": "condition-1",
                "direction": "buy_no",
                "token_id": token_id,
                "q_live": 0.81,
                "causal_snapshot_id": "source-run-1",
            },
            "2026-06-07T00:00:00Z",
        )
        insert_certificate(
            "FinalIntentCertificate",
            f"final_intent:{event_id}:intent:{token_id}",
            {
                "event_id": event_id,
                "final_intent_id": f"intent:{token_id}",
                "condition_id": "condition-1",
                "bin_label": "Will the highest temperature in Madrid be 33°C on June 8?",
                "temperature_metric": "high",
                "unit": "C",
                "decision_source_context": {
                    "city": "Madrid",
                    "target_date": "2026-06-08",
                },
            },
            "2026-06-07T00:00:01Z",
        )

        trade_case = _edli_trade_case_for_command(
            conn,
            {
                "position_id": "pos-edli",
                "decision_id": decision_id,
                "token_id": token_id,
                "env_condition_id": "condition-1",
                "env_yes_token_id": "tok-yes",
                "env_no_token_id": token_id,
            },
        )

        assert trade_case == {}

