    def test_cancelled_rest_entry_repairs_confirmed_fill_past_stale_order_fact(
        self,
        conn,
    ):
        """A cancel-after-fill race must not hide confirmed partial exposure."""

        from src.execution.command_recovery import (
            reconcile_missing_filled_entry_execution_fact_repairs,
        )

        _insert(conn, size=5.0, price=0.43)
        _advance_to_acked(conn, venue_order_id="ord-001")
        _seed_pending_entry_projection(conn)
        conn.execute(
            "UPDATE venue_commands SET state = 'CANCELLED' WHERE command_id = 'cmd-001'"
        )
        conn.execute(
            """
            UPDATE position_current
               SET phase = 'active',
                   shares = 4.0,
                   cost_basis_usd = 1.72,
                   entry_price = 0.43,
                   order_status = 'filled',
                   fill_authority = 'venue_confirmed_full',
                   chain_state = 'synced',
                   chain_shares = 4.0,
                   chain_avg_price = 0.43,
                   chain_cost_basis_usd = 1.72,
                   chain_seen_at = '2026-04-26T00:07:00Z'
             WHERE position_id = 'pos-001'
            """
        )
        _append_order_fact(
            conn,
            state="LIVE",
            matched_size="0",
            remaining_size="5",
        )
        _append_trade_fact(
            conn,
            trade_id="trade-cancel-race-1",
            state="CONFIRMED",
            filled_size="2.5",
            fill_price="0.43",
        )
        from src.riskguard.riskguard import _load_riskguard_portfolio_truth

        _portfolio, before = _load_riskguard_portfolio_truth(conn)
        assert before["consistency_lock"] == "degraded"
        assert before["unloadable_rows"] == [
            {
                "trade_id": "pos-001",
                "state": "entered",
                "reason": "fill-grade loader row missing execution_fact source provenance",
                "classification": "excluded_unaccounted",
            }
        ]
        assert reconcile_missing_filled_entry_execution_fact_repairs(conn) == {
            "scanned": 0,
            "advanced": 0,
            "stayed": 0,
            "errors": 0,
        }
        _append_trade_fact(
            conn,
            trade_id="trade-cancel-race-2",
            state="CONFIRMED",
            filled_size="1.5",
            fill_price="0.43",
        )

        traced_sql = []
        conn.set_trace_callback(traced_sql.append)
        repair_summary = reconcile_missing_filled_entry_execution_fact_repairs(conn)
        conn.set_trace_callback(None)
        assert repair_summary == {
            "scanned": 1,
            "advanced": 1,
            "stayed": 0,
            "errors": 0,
        }
        assert not any("venue_order_facts" in sql for sql in traced_sql)
        execution = conn.execute(
            """
            SELECT command_id, shares, fill_price, venue_status,
                   terminal_exec_status
              FROM execution_fact
             WHERE intent_id = 'pos-001:entry'
            """
        ).fetchone()
        assert dict(execution) == {
            "command_id": "cmd-001",
            "shares": 4.0,
            "fill_price": 0.43,
            "venue_status": "PARTIAL",
            "terminal_exec_status": "filled",
        }
        portfolio, after = _load_riskguard_portfolio_truth(conn)
        assert len(portfolio.positions) == 1
        assert after["unloadable_count"] == 0
        assert after["consistency_lock"] == "pass"
        conn.execute(
            """
            UPDATE execution_fact
               SET command_id = NULL,
                   filled_at = '1999-01-01T00:00:00Z',
                   shares = 3.0,
                   fill_price = 0.2
             WHERE intent_id = 'pos-001:entry'
            """
        )
        assert reconcile_missing_filled_entry_execution_fact_repairs(conn) == {
            "scanned": 0,
            "advanced": 0,
            "stayed": 0,
            "errors": 0,
        }
        preserved = conn.execute(
            """
            SELECT command_id, filled_at, shares, fill_price
              FROM execution_fact
             WHERE intent_id = 'pos-001:entry'
            """
        ).fetchone()
        assert dict(preserved) == {
            "command_id": None,
            "filled_at": "1999-01-01T00:00:00Z",
            "shares": 3.0,
            "fill_price": 0.2,
        }

    def test_cancelled_entry_late_fill_advances_strict_position_prefix(
        self,
        conn,
    ):
        """Cancel closes the remainder, not fills confirmed after the ACK race."""

        from src.execution.command_recovery import (
            reconcile_authenticated_entry_trade_facts,
            reconcile_filled_entry_projection_repairs,
        )
        from src.state.venue_command_repo import append_event

        _insert(conn, size=33.0, price=0.29)
        _open_test_entry_obligation(conn, "cmd-001")
        _advance_to_acked(conn, venue_order_id="ord-001")
        _seed_pending_entry_projection(conn)
        _append_confirmed_trade_fact(
            conn,
            trade_id="trade-cancelled-prefix-1",
            filled_size="3.5",
            fill_price="0.29",
        )
        assert reconcile_authenticated_entry_trade_facts(
            conn,
            command_id="cmd-001",
        ) == {"scanned": 1, "advanced": 1, "stayed": 0, "errors": 0}
        conn.execute("DELETE FROM execution_fact WHERE command_id = 'cmd-001'")
        conn.execute(
            """
            UPDATE position_current
               SET fill_authority = 'venue_confirmed_full',
                   chain_state = 'synced',
                   chain_shares = 3.5,
                   chain_avg_price = 0.29,
                   chain_cost_basis_usd = 1.015
             WHERE position_id = 'pos-001'
            """
        )
        append_event(
            conn,
            command_id="cmd-001",
            event_type="CANCEL_REQUESTED",
            occurred_at="2026-04-26T00:08:00Z",
        )
        append_event(
            conn,
            command_id="cmd-001",
            event_type="CANCEL_ACKED",
            occurred_at="2026-04-26T00:09:00Z",
        )
        _append_confirmed_trade_fact(
            conn,
            trade_id="trade-cancelled-prefix-2",
            filled_size="8",
            fill_price="0.29",
        )

        summary = reconcile_filled_entry_projection_repairs(conn)

        assert summary == {"scanned": 1, "advanced": 1, "stayed": 0, "errors": 0}
        current = conn.execute(
            """
            SELECT shares, cost_basis_usd, entry_price, chain_state, chain_shares
              FROM position_current
             WHERE position_id = 'pos-001'
            """
        ).fetchone()
        assert dict(current) == {
            "shares": 11.5,
            "cost_basis_usd": pytest.approx(3.335),
            "entry_price": pytest.approx(0.29),
            # Fill recovery does not invent a newer chain observation.  The
            # stale 3.5-share prefix remains explicit until chain reconcile.
            "chain_state": "synced",
            "chain_shares": 3.5,
        }
        execution = conn.execute(
            """
            SELECT shares, fill_price, venue_status, terminal_exec_status
              FROM execution_fact
             WHERE command_id = 'cmd-001'
               AND order_role = 'entry'
            """
        ).fetchone()
        assert dict(execution) == {
            "shares": 11.5,
            "fill_price": pytest.approx(0.29),
            "venue_status": "PARTIAL",
            "terminal_exec_status": "filled",
        }
        assert conn.execute(
            "SELECT status FROM entry_exposure_obligations WHERE command_id = 'cmd-001'"
        ).fetchone()[0] == "RESOLVED"
        assert reconcile_filled_entry_projection_repairs(conn) == {
            "scanned": 0,
            "advanced": 0,
            "stayed": 0,
            "errors": 0,
        }

